insert into questions (question_set_id, question_text, question_type, explanation, metadata, marks, sort_order) values (v_qset, 'Reading Passage 2 has six paragraphs, A–F. Choose the correct heading for each paragraph from the list of headings below. (Questions 14–19)', 'matching', 'Paragraph A: Para A — কেন পৃথিবীর অধিকাংশ পানি মানুষ ব্যবহার করতে পারে না | Paragraph B: Para B — physical ও economic scarcity-র পার্থক্য | Paragraph C: Para C — কৃষিকাজে পানির বিপুল ব্যবহার | Paragraph D: Para D — জলবায়ু পরিবর্তনে হিমবাহ সংকুচিত হওয়া | Paragraph E: Para E — ভূগর্ভস্থ পানি দ্রুত ব্যবহৃত হচ্ছে, অদৃশ্য সম্পদ | Paragraph F: Para F — সমাধানের জন্য একাধিক পদ্ধতির সমন্বয় প্রয়োজন', '{"pairs":[{"left":"Paragraph A","right":"vi. Why most of Earth’s water cannot be used by humans"},{"left":"Paragraph B","right":"i. Two different types of scarcity, one problem"},{"left":"Paragraph C","right":"ii. Why farming consumes so much of the world’s water"},{"left":"Paragraph D","right":"iii. A shrinking source of water is at risk from a warming planet"},{"left":"Paragraph E","right":"iv. An invisible resource being used faster than it can recover"},{"left":"Paragraph F","right":"v. A combination of approaches will be needed"}]}'::jsonb, 6, 14);
