-- ============================================================
-- 030_ielts_reading_practice_tests.sql
-- Content batch: 5 full IELTS Reading practice tests (3 passages,
-- 40 questions, and a Bangla-explained answer key each), transcribed
-- from "IELTS Reading Band 5.5 to 8", under IELTS > Reading >
-- Practice Tests. Each test is one lesson (the passages + questions
-- as a readable test paper) paired 1:1 with its own auto-gradable
-- 40-question practice set via lesson_id.
-- ============================================================

do $$
declare
  v_practice_tests uuid;
  v_lesson uuid;
  v_qset uuid;
  v_q uuid;
begin
  select cn.id into v_practice_tests from content_nodes cn
    join content_nodes reading on cn.parent_id = reading.id
    join content_nodes ielts on reading.parent_id = ielts.id
    where ielts.slug = 'ielts' and reading.slug = 'reading' and cn.slug = 'practice-tests';

  -- Test 1
  values (v_practice_tests, 'Test 1: Chocolate / Circadian Rhythms / AI in Everyday Life', 'test-1', 'A full IELTS Reading practice test (3 passages, 40 questions) from "IELTS Reading Band 5.5 to 8".', '{"type":"doc","content":[{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Set a timer for 60 minutes (20 minutes per passage) before you start. Attempt the whole test without checking answers, then click Start Practice below to grade yourself and see the explanation for every question."}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Reading Passage 1: The Story of Chocolate"}]},{"type":"paragraph","content":[{"type":"text","text":"Long before chocolate became the sweet confectionery enjoyed around the world today, it began as a bitter beverage consumed by the early civilisations of Mesoamerica. The cacao tree, from which all chocolate is ultimately derived, is native to the tropical regions of Central and South America. Archaeological evidence suggests that the Olmec, one of the earliest civilisations to flourish in the region, were consuming cacao in some form as far back as 1500 BCE, though they left no written records explaining exactly how it was prepared."}]},{"type":"paragraph","content":[{"type":"text","text":"The practice was later adopted and elaborated upon by the Maya and, subsequently, the Aztec civilisations, both of whom held cacao in extremely high regard. Cacao beans were mixed with water, chilli peppers and other spices to produce a frothy, bitter drink that was far removed from the sweet treat familiar today. Among the Aztecs, cacao beans became so highly valued that they were used as a form of currency, and the drink itself was largely reserved for nobles, priests and warriors rather than ordinary citizens."}]},{"type":"paragraph","content":[{"type":"text","text":"Cacao first reached Europe in the sixteenth century, following the Spanish conquest of Mesoamerica. Spanish colonists and missionaries began exporting cacao beans back to Spain, where the drink was gradually transformed to suit European tastes. Sugar and, later, vanilla were added to counteract the natural bitterness, and the resulting sweetened beverage quickly became a fashionable, if expensive, drink among the European aristocracy. For roughly a century, Spain managed to keep the recipe largely secret from the rest of the continent, but by the 1600s knowledge of chocolate had spread to France, Italy and England."}]},{"type":"paragraph","content":[{"type":"text","text":"The transformation of chocolate from an exclusive drink into an affordable, solid confection depended on a series of technical innovations during the nineteenth century. In 1828, a Dutch chemist developed a hydraulic press capable of separating cocoa butter from roasted, ground cacao beans, leaving behind a fine powder that could be mixed with liquids far more easily than before. This innovation also produced surplus cocoa butter, which manufacturers later combined with cocoa powder and sugar to create the first solid chocolate bars in England in the 1840s."}]},{"type":"paragraph","content":[{"type":"text","text":"Milk chocolate, now the most widely consumed variety in many countries, was not developed until several decades later, when a Swiss manufacturer discovered a method of blending condensed milk with chocolate liquor to produce a smoother, creamier product. By the early twentieth century, industrial manufacturing techniques had made chocolate affordable enough for mass consumption, and it rapidly evolved from a luxury item into an everyday product sold in shops across the world."}]},{"type":"paragraph","content":[{"type":"text","text":"Today, cacao cultivation has shifted dramatically away from its original home in the Americas. The majority of the world’s cacao is now grown in West Africa, particularly in Ivory Coast and Ghana, which together supply well over half of global production. This shift has brought its own set of challenges, including persistent concerns about labour practices on some cacao farms, which have prompted the growth of certification schemes intended to guarantee fairer conditions and prices for farmers."}]},{"type":"heading","attrs":{"level":4},"content":[{"type":"text","text":"Questions 1–7"}]},{"type":"paragraph","content":[{"type":"text","text":"1. ","marks":[{"type":"bold"}]},{"type":"text","text":"The Olmec left written records describing exactly how they prepared cacao."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A. True"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"B. False"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"C. Not Given"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"2. ","marks":[{"type":"bold"}]},{"type":"text","text":"Among the Aztecs, cacao beans were sometimes used as a method of payment."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A. True"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"B. False"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"C. Not Given"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"3. ","marks":[{"type":"bold"}]},{"type":"text","text":"In Aztec society, the cacao drink was consumed mainly by ordinary citizens."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A. True"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"B. False"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"C. Not Given"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"4. ","marks":[{"type":"bold"}]},{"type":"text","text":"Spain successfully kept the chocolate recipe secret from the rest of Europe indefinitely."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A. True"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"B. False"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"C. Not Given"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"5. ","marks":[{"type":"bold"}]},{"type":"text","text":"Vanilla was one of the ingredients added to make cacao more palatable to Europeans."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A. True"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"B. False"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"C. Not Given"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"6. ","marks":[{"type":"bold"}]},{"type":"text","text":"The Dutch chemist who invented the cocoa press was later honoured with a national award."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A. True"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"B. False"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"C. Not Given"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"7. ","marks":[{"type":"bold"}]},{"type":"text","text":"West Africa now produces more than half of the world’s cacao."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A. True"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"B. False"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"C. Not Given"}]}]}]},{"type":"heading","attrs":{"level":4},"content":[{"type":"text","text":"Questions 8–13"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"8. ","marks":[{"type":"bold"}]},{"type":"text","text":"Complete the sentences below. Use NO MORE THAN TWO WORDS AND/OR A NUMBER for each answer. Cacao was originally consumed as a bitter ........... rather than a sweet food."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"9. ","marks":[{"type":"bold"}]},{"type":"text","text":"Complete the sentences below. Use NO MORE THAN TWO WORDS AND/OR A NUMBER for each answer. The Aztecs used cacao beans as a form of ........... ."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"10. ","marks":[{"type":"bold"}]},{"type":"text","text":"Complete the sentences below. Use NO MORE THAN TWO WORDS AND/OR A NUMBER for each answer. In Europe, the natural bitterness of cacao was reduced by adding sugar and ........... ."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"11. ","marks":[{"type":"bold"}]},{"type":"text","text":"Complete the sentences below. Use NO MORE THAN TWO WORDS AND/OR A NUMBER for each answer. By the ........... , knowledge of chocolate had spread beyond Spain to other European countries."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"12. ","marks":[{"type":"bold"}]},{"type":"text","text":"Complete the sentences below. Use NO MORE THAN TWO WORDS AND/OR A NUMBER for each answer. In 1828, a Dutch chemist invented a ........... capable of separating cocoa butter from cacao beans."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"13. ","marks":[{"type":"bold"}]},{"type":"text","text":"Complete the sentences below. Use NO MORE THAN TWO WORDS AND/OR A NUMBER for each answer. The two leading producers of cacao today are Ivory Coast and ........... ."}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Reading Passage 2: Circadian Rhythms and the Science of Sleep"}]},{"type":"paragraph","content":[{"type":"text","text":"Paragraph A. ","marks":[{"type":"bold"}]},{"type":"text","text":"Nearly every living organism, from single-celled algae to human beings, possesses an internal biological clock that follows a roughly 24-hour cycle. This clock, known as the circadian rhythm — from the Latin circa diem, meaning “about a day” — governs far more than simply when we feel sleepy. It regulates body temperature, hormone release, appetite and even the timing of cell repair, quietly shaping the rhythm of daily life in ways most people never consciously notice."}]},{"type":"paragraph","content":[{"type":"text","text":"Paragraph B. ","marks":[{"type":"bold"}]},{"type":"text","text":"It was not until the 1970s that scientists identified the precise location of this internal clock: a small cluster of neurons in the hypothalamus known as the suprachiasmatic nucleus, or SCN. The SCN receives information directly from the retina, allowing it to detect changes in light and dark. Light is the primary external cue, known as a zeitgeber, that resets the clock each day, which explains why exposure to daylight in the morning is so effective at correcting a disrupted sleep schedule."}]},{"type":"paragraph","content":[{"type":"text","text":"Paragraph C. ","marks":[{"type":"bold"}]},{"type":"text","text":"One of the clock’s most important outputs is melatonin, a hormone produced by the pineal gland in response to darkness. As light fades in the evening, melatonin levels rise, signalling to the body that it is time to prepare for sleep. Unfortunately, artificial light — particularly the blue light emitted by phones, tablets and computer screens — can suppress melatonin production, tricking the brain into believing it is still daytime and delaying the onset of sleep, sometimes by an hour or more."}]},{"type":"paragraph","content":[{"type":"text","text":"Paragraph D. ","marks":[{"type":"bold"}]},{"type":"text","text":"Not everyone’s clock runs on exactly the same schedule. Individual variation in circadian timing gives rise to what researchers call chronotypes, popularly described as “larks”, who wake and feel most alert early in the day, and “owls”, who naturally function better later in the evening. These preferences appear to be substantially influenced by genetics. Notably, adolescents undergo a temporary shift towards a later chronotype during puberty, which places them at odds with early school start times — a mismatch that some researchers argue contributes to widespread sleep deprivation among teenagers."}]},{"type":"paragraph","content":[{"type":"text","text":"Paragraph E. ","marks":[{"type":"bold"}]},{"type":"text","text":"Chronic disruption of the circadian rhythm, whether through shift work, frequent long-haul travel or simply irregular sleep habits, has been linked to a range of health problems. These include impaired concentration and memory, a weakened immune response, and an increased risk of cardiovascular disease and metabolic disorders such as type 2 diabetes. Shift workers, whose sleep schedules are frequently misaligned with natural light patterns, appear to be at particularly elevated risk."}]},{"type":"paragraph","content":[{"type":"text","text":"Paragraph F. ","marks":[{"type":"bold"}]},{"type":"text","text":"In response to this growing body of evidence, a number of practical interventions have emerged. Controlled light therapy is now commonly used to treat jet lag and seasonal affective disorder, while some workplaces have introduced carefully scheduled light exposure for night-shift employees. Perhaps most notably, chronobiology research has fuelled growing calls for schools to delay their start times, on the grounds that doing so would better align the school day with adolescents’ natural sleep patterns — a policy change that a small but increasing number of institutions have begun to adopt."}]},{"type":"heading","attrs":{"level":4},"content":[{"type":"text","text":"Question 14-19"}]},{"type":"paragraph","content":[{"type":"text","text":"Reading Passage 2 has six paragraphs, A–F. Choose the correct heading for each paragraph from the list of headings below. (Questions 14–19)"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"i. The hormone that signals darkness has arrived"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"iii. A biological clock shared by nearly all living things"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"iv. Individual differences in sleeping preferences"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"v. The health risks of a disrupted body clock"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"vi. Practical steps being taken to reduce the effects of disruption"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"viii. The discovery of the brain region controlling our internal clock"}]}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Paragraph A"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Paragraph B"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Paragraph C"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Paragraph D"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Paragraph E"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Paragraph F"}]}]}]},{"type":"heading","attrs":{"level":4},"content":[{"type":"text","text":"Questions 20–26"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"20. ","marks":[{"type":"bold"}]},{"type":"text","text":"Which paragraph contains the following information? Write the correct letter, A–F. a comparison between two different types of people based on their natural sleep preference"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"21. ","marks":[{"type":"bold"}]},{"type":"text","text":"Which paragraph contains the following information? Write the correct letter, A–F. a reference to a specific part of the brain"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"22. ","marks":[{"type":"bold"}]},{"type":"text","text":"Which paragraph contains the following information? Write the correct letter, A–F. an explanation of why looking at screens before bed can be problematic"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"23. ","marks":[{"type":"bold"}]},{"type":"text","text":"Which paragraph contains the following information? Write the correct letter, A–F. a suggestion that institutions should reconsider their daily schedules"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"24. ","marks":[{"type":"bold"}]},{"type":"text","text":"What is the term for an external cue, such as light, that resets the body’s internal clock?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"25. ","marks":[{"type":"bold"}]},{"type":"text","text":"Which gland produces melatonin?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"26. ","marks":[{"type":"bold"}]},{"type":"text","text":"What term is used to describe someone who naturally prefers to sleep and wake early?"}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Reading Passage 3: Artificial Intelligence in Everyday Life"}]},{"type":"paragraph","content":[{"type":"text","text":"Artificial intelligence, once confined largely to research laboratories, is now woven into the fabric of daily life. Recommendation algorithms decide which films appear at the top of a streaming service, voice assistants answer spoken questions, navigation apps predict traffic in real time, and spam filters quietly sort unwanted email before it ever reaches an inbox. Most people interact with some form of AI system dozens of times a day, often without any awareness that they are doing so."}]},{"type":"paragraph","content":[{"type":"text","text":"Much of this is powered by machine learning, a branch of AI in which systems improve their performance through exposure to large volumes of data rather than through being explicitly programmed for every possible scenario. This approach enables remarkable personalisation, but it also raises a well-known difficulty sometimes referred to as the black box problem: the process by which certain AI systems reach a specific decision can be so complex that even the engineers who built the system cannot always fully explain a particular output."}]},{"type":"paragraph","content":[{"type":"text","text":"Some critics have called for AI to be banned outright from sensitive areas such as hiring decisions or loan approvals. This position, in my view, overstates the case. The underlying problem is not artificial intelligence itself, but a lack of adequate regulation and transparency requirements. When properly regulated and audited, algorithmic decision-making has the potential to reduce human bias rather than amplify it, since a well-designed algorithm does not tire, does not hold conscious prejudice, and applies the same criteria consistently to every case. That said, algorithms are not inherently neutral: they can inherit and even reinforce biases present in their training data if that data reflects historical inequalities."}]},{"type":"paragraph","content":[{"type":"text","text":"The effect of AI on employment remains a particularly contentious question. Certain categories of work, such as routine data entry and basic customer service, have already been partly displaced by automated systems. At the same time, entirely new roles have emerged, including AI trainers, algorithmic auditors and AI ethics specialists. Despite confident predictions from commentators on both sides, economists remain genuinely divided, and the net long-term effect on overall employment is, at present, impossible to state with any real certainty."}]},{"type":"paragraph","content":[{"type":"text","text":"Looking ahead, AI is likely to become further embedded in healthcare, where it already assists in diagnostic imaging, and in education, where adaptive tutoring systems can personalise instruction to an individual student’s pace. Autonomous vehicles, too, continue to move gradually towards wider deployment. Yet public trust in these technologies will ultimately depend on demonstrated reliability and clear accountability when systems fail, not merely on technical capability. A self-driving car that performs perfectly ninety-nine times out of a hundred will not earn public confidence unless there is a transparent and trustworthy answer to what happens on the hundredth occasion."}]},{"type":"heading","attrs":{"level":4},"content":[{"type":"text","text":"Questions 27–31"}]},{"type":"paragraph","content":[{"type":"text","text":"27. ","marks":[{"type":"bold"}]},{"type":"text","text":"According to the passage, most people encounter AI systems"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A. only when they use voice assistants"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"B. mainly in specialised research settings"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"C. many times a day, often without noticing"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"D. rarely, since AI use remains uncommon"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"28. ","marks":[{"type":"bold"}]},{"type":"text","text":"What is the “black box problem” mentioned in the passage?"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A. AI systems that malfunction during data storage"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"B. the difficulty of fully explaining how certain AI decisions are reached"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"C. a lack of available data for training AI systems"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"D. AI systems that intentionally hide information from developers"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"29. ","marks":[{"type":"bold"}]},{"type":"text","text":"What is the author’s main argument about calls for a complete ban on AI in areas like hiring?"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A. The bans are fully justified given current risks"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"B. AI should never be used in decisions affecting people’s lives"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"C. The core problem lies in inadequate regulation, not AI itself"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"D. Only governments should be allowed to develop AI systems"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"30. ","marks":[{"type":"bold"}]},{"type":"text","text":"According to the passage, algorithmic bias can occur because"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A. algorithms deliberately favour certain groups"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"B. training data may contain existing human biases"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"C. developers intentionally programme unfair rules"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"D. AI systems are incapable of processing large datasets"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"31. ","marks":[{"type":"bold"}]},{"type":"text","text":"What does the author say about AI’s effect on employment?"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A. It will definitely lead to mass unemployment"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"B. It will have no effect on the job market at all"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"C. Economists broadly agree that new jobs will outnumber losses"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"D. The overall impact remains genuinely uncertain"}]}]}]},{"type":"heading","attrs":{"level":4},"content":[{"type":"text","text":"Questions 32–36"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"32. ","marks":[{"type":"bold"}]},{"type":"text","text":"Complete the summary below. Use NO MORE THAN TWO WORDS for each answer. Blank (32). Summary: AI has become deeply embedded in (32)........... life, often operating without users’ awareness. A key concern is the (33)........... problem, where even developers cannot always explain specific outcomes. The author argues that the central issue is not AI itself but a lack of proper (34)........... . While algorithms can inherit bias from their (35)........... , they are not inherently prejudiced in the way humans can be. Looking ahead, public confidence in AI will depend on reliability and clear (36)........... when systems fail."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"33. ","marks":[{"type":"bold"}]},{"type":"text","text":"Complete the summary below. Use NO MORE THAN TWO WORDS for each answer. Blank (33). Summary: AI has become deeply embedded in (32)........... life, often operating without users’ awareness. A key concern is the (33)........... problem, where even developers cannot always explain specific outcomes. The author argues that the central issue is not AI itself but a lack of proper (34)........... . While algorithms can inherit bias from their (35)........... , they are not inherently prejudiced in the way humans can be. Looking ahead, public confidence in AI will depend on reliability and clear (36)........... when systems fail."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"34. ","marks":[{"type":"bold"}]},{"type":"text","text":"Complete the summary below. Use NO MORE THAN TWO WORDS for each answer. Blank (34). Summary: AI has become deeply embedded in (32)........... life, often operating without users’ awareness. A key concern is the (33)........... problem, where even developers cannot always explain specific outcomes. The author argues that the central issue is not AI itself but a lack of proper (34)........... . While algorithms can inherit bias from their (35)........... , they are not inherently prejudiced in the way humans can be. Looking ahead, public confidence in AI will depend on reliability and clear (36)........... when systems fail."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"35. ","marks":[{"type":"bold"}]},{"type":"text","text":"Complete the summary below. Use NO MORE THAN TWO WORDS for each answer. Blank (35). Summary: AI has become deeply embedded in (32)........... life, often operating without users’ awareness. A key concern is the (33)........... problem, where even developers cannot always explain specific outcomes. The author argues that the central issue is not AI itself but a lack of proper (34)........... . While algorithms can inherit bias from their (35)........... , they are not inherently prejudiced in the way humans can be. Looking ahead, public confidence in AI will depend on reliability and clear (36)........... when systems fail."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"36. ","marks":[{"type":"bold"}]},{"type":"text","text":"Complete the summary below. Use NO MORE THAN TWO WORDS for each answer. Blank (36). Summary: AI has become deeply embedded in (32)........... life, often operating without users’ awareness. A key concern is the (33)........... problem, where even developers cannot always explain specific outcomes. The author argues that the central issue is not AI itself but a lack of proper (34)........... . While algorithms can inherit bias from their (35)........... , they are not inherently prejudiced in the way humans can be. Looking ahead, public confidence in AI will depend on reliability and clear (36)........... when systems fail."}]}]}]},{"type":"heading","attrs":{"level":4},"content":[{"type":"text","text":"Questions 37–40"}]},{"type":"paragraph","content":[{"type":"text","text":"37. ","marks":[{"type":"bold"}]},{"type":"text","text":"The author believes that AI should be completely banned from sensitive decision-making areas such as hiring."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A. Yes"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"B. No"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"C. Not Given"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"38. ","marks":[{"type":"bold"}]},{"type":"text","text":"The author suggests that well-regulated algorithms could potentially reduce bias compared with human decision-makers."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A. Yes"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"B. No"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"C. Not Given"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"39. ","marks":[{"type":"bold"}]},{"type":"text","text":"The author personally worked as an AI researcher before writing this article."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A. Yes"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"B. No"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"C. Not Given"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"40. ","marks":[{"type":"bold"}]},{"type":"text","text":"The author argues that technical capability alone will be enough to secure public trust in AI."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A. Yes"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"B. No"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"C. Not Given"}]}]}]}]}'::jsonb, 'published', 'advanced', 60, now())
  returning id into v_lesson;

  values (v_lesson, 'Practice: Test 1: Chocolate / Circadian Rhythms / AI in Everyday Life', 'Grade your answers and see the explanation for every question.', 'advanced', 60, 40, true)
  returning id into v_qset;




































